import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Button, Space, Spin, Alert, Empty, message, Tooltip } from 'antd';
import { CopyOutlined, ReloadOutlined } from '@ant-design/icons';
import mermaid from 'mermaid';
import { useQuery } from '@tanstack/react-query';
import { apiClient } from '../../../../services/api';
import { Task, TaskDependency, TaskStatus } from '../../../../types';
import { generateMermaidGraph, STATUS_LABELS } from '../../utils/mermaidGenerator';

interface TaskMermaidViewProps {
  moduleId?: string;
  onTaskSelect?: (taskId: string) => void;
  refreshKey?: number;
}

/** 状态图例颜色 */
const LEGEND_COLORS: Record<TaskStatus, string> = {
  ready: '#1890ff',
  claimed: '#722ed1',
  in_progress: '#fa8c16',
  pending_review: '#13c2c2',
  completed: '#52c41a',
  failed: '#f5222d',
  blocked: '#8c8c8c',
};

let mermaidInitialized = false;

const TaskMermaidView: React.FC<TaskMermaidViewProps> = ({
  moduleId,
  onTaskSelect,
  refreshKey,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [svgContent, setSvgContent] = useState<string>('');
  const [renderError, setRenderError] = useState<string>('');
  const [isRendering, setIsRendering] = useState(false);
  const renderCountRef = useRef(0);

  // 获取任务列表
  const { data: tasksData, isLoading: tasksLoading } = useQuery({
    queryKey: ['tasks', moduleId ?? 'all', refreshKey],
    queryFn: async () => {
      const params: Record<string, any> = { pageSize: 200 };
      if (moduleId) params.moduleId = moduleId;
      const response = await apiClient.get('/tasks', { params });
      return response.data;
    },
  });

  // 获取依赖关系
  const { data: depsData, isLoading: depsLoading } = useQuery({
    queryKey: ['dependencies', moduleId ?? 'all', refreshKey],
    queryFn: async () => {
      const params: Record<string, any> = {};
      if (moduleId) params.moduleId = moduleId;
      const response = await apiClient.get('/dependencies', { params });
      return response.data;
    },
  });

  const tasks: Task[] = tasksData?.tasks || [];
  const dependencies: TaskDependency[] = depsData?.dependencies || [];

  // 初始化 mermaid
  useEffect(() => {
    if (!mermaidInitialized) {
      mermaid.initialize({
        startOnLoad: false,
        theme: 'dark',
        flowchart: {
          useMaxWidth: true,
          htmlLabels: true,
          curve: 'basis',
        },
        securityLevel: 'loose',
      });
      mermaidInitialized = true;
    }
  }, []);

  // 生成 mermaid 图定义
  const graphDefinition = generateMermaidGraph(tasks, dependencies);

  // 渲染 mermaid 图
  const renderMermaid = useCallback(async () => {
    if (tasksLoading || depsLoading) return;

    setIsRendering(true);
    setRenderError('');

    try {
      renderCountRef.current += 1;
      const uniqueId = `mermaid-graph-${Date.now()}-${renderCountRef.current}`;
      const { svg } = await mermaid.render(uniqueId, graphDefinition);
      setSvgContent(svg);
    } catch (err: any) {
      console.error('Mermaid render error:', err);
      setRenderError(err?.message || '图表渲染失败');
    } finally {
      setIsRendering(false);
    }
  }, [graphDefinition, tasksLoading, depsLoading]);

  useEffect(() => {
    renderMermaid();
  }, [renderMermaid]);

  // 注入 SVG 到容器
  useEffect(() => {
    if (containerRef.current && svgContent) {
      containerRef.current.innerHTML = svgContent;

      // 为节点添加点击事件
      if (onTaskSelect) {
        const svgEl = containerRef.current.querySelector('svg');
        if (svgEl) {
          // 为每个任务节点绑定点击
          tasks.forEach((task) => {
            const safeId = `task_${task.id.replace(/-/g, '_')}`;
            const nodeEl = svgEl.querySelector(`#${safeId}, [id="${safeId}"]`);
            if (nodeEl) {
              (nodeEl as HTMLElement).style.cursor = 'pointer';
              nodeEl.addEventListener('click', () => {
                onTaskSelect(task.id);
              });
            }
          });
        }
      }
    }
  }, [svgContent, tasks, onTaskSelect]);

  // 复制 Mermaid 代码
  const handleCopyCode = () => {
    navigator.clipboard
      .writeText(graphDefinition)
      .then(() => {
        message.success('Mermaid 代码已复制到剪贴板');
      })
      .catch(() => {
        message.error('复制失败，请手动复制');
      });
  };

  const isLoading = tasksLoading || depsLoading || isRendering;

  return (
    <div style={{ position: 'relative' }}>
      {/* 工具栏 */}
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: 12,
        }}
      >
        {/* 状态图例 */}
        <Space wrap size={8}>
          {(Object.entries(STATUS_LABELS) as [TaskStatus, string][]).map(([status, label]) => (
            <span
              key={status}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 4,
                fontSize: 12,
              }}
            >
              <span
                style={{
                  display: 'inline-block',
                  width: 10,
                  height: 10,
                  borderRadius: 2,
                  backgroundColor: LEGEND_COLORS[status],
                }}
              />
              {label}
            </span>
          ))}
        </Space>

        {/* 操作按钮 */}
        <Space>
          <Tooltip title="重新渲染">
            <Button
              icon={<ReloadOutlined />}
              size="small"
              onClick={renderMermaid}
              loading={isRendering}
            >
              刷新
            </Button>
          </Tooltip>
          <Tooltip title="复制 Mermaid 代码">
            <Button
              icon={<CopyOutlined />}
              size="small"
              onClick={handleCopyCode}
            >
              复制代码
            </Button>
          </Tooltip>
        </Space>
      </div>

      {/* 图表区域 */}
      {isLoading && !svgContent ? (
        <div
          style={{
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            height: 400,
          }}
        >
          <Spin tip="正在渲染流程图..." size="large" />
        </div>
      ) : renderError ? (
        <Alert
          type="error"
          message="图表渲染失败"
          description={
            <div>
              <p>{renderError}</p>
              <details style={{ marginTop: 8 }}>
                <summary style={{ cursor: 'pointer', color: '#1890ff' }}>
                  查看 Mermaid 代码
                </summary>
                <pre
                  style={{
                    marginTop: 8,
                    padding: 8,
                    background: '#1a1a2e',
                    borderRadius: 4,
                    overflow: 'auto',
                    fontSize: 12,
                    color: '#e0e0e0',
                  }}
                >
                  {graphDefinition}
                </pre>
              </details>
            </div>
          }
          action={
            <Button size="small" onClick={renderMermaid}>
              重试
            </Button>
          }
        />
      ) : tasks.length === 0 ? (
        <Empty description="暂无任务数据，请先创建任务" style={{ padding: '60px 0' }} />
      ) : (
        <div
          style={{
            position: 'relative',
            minHeight: 400,
            background: '#1a1a2e',
            borderRadius: 8,
            padding: 16,
            overflow: 'auto',
          }}
        >
          {isRendering && (
            <div
              style={{
                position: 'absolute',
                top: '50%',
                left: '50%',
                transform: 'translate(-50%, -50%)',
                zIndex: 10,
              }}
            >
              <Spin />
            </div>
          )}
          <div
            ref={containerRef}
            style={{
              width: '100%',
              opacity: isRendering ? 0.5 : 1,
              transition: 'opacity 0.2s',
            }}
          />
        </div>
      )}
    </div>
  );
};

export default TaskMermaidView;
